INSERT INTO park (id, name, description, latitude, longitude, phone, province_id, wikipedia) VALUES
  (1, 'Parc national Tsingy de Bemaraha', 'Vaste site idéal pour randonner, connu pour ses formations géologiques calcaires en forme d''aiguille, et vue.', -18.919803, 44.794327, '+261320940131', 6, 'fr:Réserve naturelle intégrale du Tsingy de Bemaraha'),
  (2, 'Parc national d''Andasibe-Mantadia', 'Forêt tropicale pittoresque, nombreux lémuriens et sentiers de randonnée entourés de flore et de faune variées.', -18.835021, 48.458685, '+261331444031', 5, 'fr:Parc national d''Andasibe-Mantadia'),
  (3, 'Parc National du Marojejy', 'Parc National Terrestre classé Patrimoine Mondial, massif impressionnant, forêt dense humide de basse altitude habitat du Propithecus candidus ou Simpona fotsy, des palmiers et des Ptéridophytes, forêt secondaire de basse altitude, forêt dense humide de montagne, brousse éricoïde.', -14.443074, 49.739961, '+261208807027', 2, 'fr:Parc national de Marojejy'),
  (4, 'Parc de Ranomafana', 'Les visites se font avec guide dans cette réserve tropicale dont la faune compte lémuriens et caméléons.', -21.264221, 47.419345, '+261207552302', 3, 'fr:Parc national de Ranomafana'),
  (5, 'Parc national de Masoala', 'Parc National Terrestre classé Site Patrimoine Mondial , forêt dense humide de moyenne altitude 0-800 m, forêt littorale orientale; habitats des Maki vari roux endémique locale, des palmiers très rares et endémique de la région, des Nepenthes masoalensis, plantes carnivores endémiques de Masoala. Mais aussi de récif corallien, habitat des tortues marines. Le Parc recèle 50% des faunes et flores de Madagascar.', -15.637402, 50.101715, '+261320940352', 2, 'fr:Parc national de Masoala'),
  (6, 'Parc national Zahamena', 'Parc National Terrestre classé Site Patrimoine Mondial, forêt dense humide sempervirente de basse altitude (400-800 m) et Forêt dense humide sempervirente de moyenne altitude (800-1200 m), habitat des lémuriens Propithecus diadema diadema,(Simpona), Eulemur fulvus fulvus, et le gecko Paroedura masobe. Mais aussi des Dypsis fibrosa et Pygeum africanum.', -17.612241, 48.779387, '+261205730024', 5, 'fr:Parc national de Zahamena'),
  (7, 'Parc national Mananara Nord', 'Parc National Terrestre et Réserve du Biosphère de l’UNESCO, centre d’endémisme des invertébrés, plusieurs espèces de poissons dans la Parc Marin, forêt dense humide de basse altitude, îlot granitique, plages, récifs coralliens.', -16.492251, 49.711958, '+261320940156', 4, 'fr:Parc national de Mananara-Nord'),
  (8, 'Makira National Park', 'L''une des plus grandes aires protégées de Madagascar, les forêts de Makira représentent l''une des plus grandes étendues de forêt humide laissées dans le biome de la forêt pluviale orientale biologiquement riche de Madagascar contient environ 50% de la biodiversité florale de Madagascar et abrite la plus grande diversité de lémuriens du pays avec 17 espèces ainsi qu''un total de un total de 125 espèces d''oiseaux dont 75 endémiques de Madagascar.', -15.407918, 49.556139, '+261345917304', 5, 'en:Makira Natural Park'),
  (9, 'Parc forestier d''Angavokely et Angavobe', 'Angavokely est une montagne, à proximité de Nandihizana, à l’est d’Antananarivo. Angavokely est composé de deux principaux massifs granitiques: celui d’Angavokely, 1752m d’altitude et celui d’Angavobe, vers la gauche, 1755m. Les circuits proposés par les guides vous permettront de découvrir les cinq cavernes, le rocher d’Ambatomisondrotra ainsi que les deux grottes d’Andavabatomaizina et d’Andavatsongomby, à l’est puis celle du « bain de la reine » à l’ouest.', -18.918517, 47.741851, '+261343315443', 1, NULL),
  (10, 'Zoo de Tsimbazaza', 'Zoo et jardin botanique ouvert en 1990 comportant un musée avec des squelettes et des sculptures tribales.', -18.929736, 47.526111, '+261202231149', 1, 'fr:Parc botanique et zoologique de Tsimbazaza'),
  (11, 'Arboretum d''Antsokay', 'L’Arboretum d''Antsokay est un parc botanique situé à 12 km au sud-est de la ville de Toliara. Plus de 900 espèces y sont conservées dont 90 % sont endémiques à la région du sud-ouest de Madagascar et 80 % ont des vertus médicinales.', -23.413794, 43.756617, '+261340760015', 6, 'fr:Arboretum d''Antsokay'),
  (12, 'Parc National Andringitra', 'Parc National Terrestre classé Site Patrimoine Mondial, refuge des plantes et animaux du massif forestier du Moyen Est de Madagascar, forêt à basse altitude, forêt de montagne, prairie altimontante, population de lémuriens, population de palmier Ravenea glauca.', -22.213675, 46.922181, '+261320940305', 3, 'fr:Parc national d''Andringitra'),
  (13, 'Lemurs Park', 'Lemurs'' Park est un parc zoologique privé situé à 25 km d''Antananarivo à Madagascar. Créé en 2001 dans le but de vulgariser la découverte des différentes espèces de lémuriens qui existent à Madagascar, l''objectif à long terme est de les réintroduire dans leur milieu naturel.', -18.954119, 47.358701, '+261331125259', 1, 'en:Lemurs'' Park'),
  (14, 'Ponton du Jardin des Baobabs', 'Espace à surveiller et reboiser.
INSERT INTO forum_post (id, body, user_id, created_at) VALUES
  (1, 'Magnifique endroit l''eau est très clair et l''on peut admirer les poissons et les coraux rapidement. Très belle vue depuis le phare. Repas sur la plage excellent. Je vous le conseille fortement!!', 1, '2020-11-13T18:00:00Z'),
  (2, 'J''y suis déjà allé, le snorkeling est top la faune sous-marine est très développée, on peut nager avec les tortues grâce à la protection de l''environnement, aller-retour en bateau compter à partir de 120000 MGA déjeuner compris. Je conseille aussi!', 3, '2020-11-13T19:00:00Z'),
  (3, 'Le Parc national d''Andasibe-Mantadia est également superbe!
